#!/bin/sh
# Regenerates internal/contract's tables of tmux's commands, options and hooks
# from a tmux source tree (the pinned version's release tarball, unpacked):
#
#   scripts/gen-contract-tables.sh <tmux source dir>
set -eu
src=$1
root=$(cd "$(dirname "$0")/.." && pwd)
ver=$(sed -n 's/^AC_INIT(\[tmux\], *\([^]]*\)).*/\1/p' "$src/configure.ac")

{
	cat <<HEAD
// Code generated by scripts/gen-contract-tables.sh from tmux $ver; DO NOT EDIT.

package contract

// tmux $ver's command table: name, alias and getopt flag spec (a letter followed by ':' takes a
// value). It is read from tmux's cmd-*.c (ISC license, Copyright (c) Nicholas Marriott and
// contributors) and used only to tell flags from their values when reading recorded calls.
var tmuxCommands = []commandSpec{
HEAD
	grep -h -A6 'const struct cmd_entry cmd_' "$src"/cmd-*.c |
		grep -E '\.name|\.alias|\.args' | paste - - - |
		sed -E 's/.*\.name = "([^"]+)".*\.alias = ("[^"]*"|NULL).*\.args = \{ "([^"]*)", .*/\1 \2 \3/' |
		sort | awk '{a=$2; if (a=="NULL") a="\"\""; printf "\t{\"%s\", %s, \"%s\"},\n", $1, a, $3}'
	echo "}"
} >"$root/internal/contract/specs.go"

{
	cat <<HEAD
// Code generated by scripts/gen-contract-tables.sh from tmux $ver; DO NOT EDIT.

package contract

// tmux $ver's options with their scopes, read from tmux's options-table.c (ISC license,
// Copyright (c) Nicholas Marriott and contributors).
var tmuxOptions = map[string]string{
HEAD
	awk '
	/\{ \.name = "/ { name = $0; sub(/.*\.name = "/, "", name); sub(/".*/, "", name) }
	/\.scope = / {
		s = $0; sub(/.*\.scope = /, "", s); sub(/,.*/, "", s)
		gsub(/OPTIONS_TABLE_/, "", s); s = tolower(s)
		if (name != "") { printf "\t\"%s\": \"%s\",\n", name, s; name = "" }
	}' "$src/options-table.c"
	echo "}"
	echo
	echo "// tmux $ver's hooks."
	echo "var tmuxHooks = map[string]bool{"
	{
		grep -oE 'OPTIONS_TABLE_(PANE_|WINDOW_|SESSION_)?HOOK\("[a-z-]+"' "$src/options-table.c" |
			sed -E 's/.*\("([a-z-]+)"/\1/'
		grep -oE 'OPTIONS_TABLE_AFTER_HOOK\("[a-z-]+"' "$src/options-table.c" |
			sed -E 's/.*\("([a-z-]+)"/after-\1/'
	} | grep -v '^after-$' | sort -u | sed 's/.*/\t"&": true,/'
	echo "}"
} >"$root/internal/contract/options_table.go"
gofmt -w "$root/internal/contract/specs.go" "$root/internal/contract/options_table.go"
